import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Featherless AI (BYOK Provider)","description":"","frontmatter":{"title":"Featherless AI (BYOK Provider)"},"headers":[],"relativePath":"providers/featherless.md","filePath":"providers/featherless.md"}`),a={name:`providers/featherless.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="featherless-ai-mode-byok" tabindex="-1">Featherless AI (Mode BYOK) <a class="header-anchor" href="#featherless-ai-mode-byok" aria-label="Permalink to “Featherless AI (Mode BYOK)”">​</a></h1><p><strong>Featherless AI</strong> beda dari provider lain di panduan ini: ia bukan bayar-per-token, melainkan penyedia <em>serverless</em> untuk <strong>model open-weight</strong> — Llama, Qwen, DeepSeek, GLM, Kimi, dan ribuan lainnya — dengan <strong>langganan flat-rate</strong>. Katalognya 40.000+ model, dan layanan ini dirancang populer di komunitas <strong>SillyTavern / RisuAI</strong> untuk <em>roleplay</em> dan cerita panjang — profil pemakaian yang sangat mirip dengan user Mikazuki. Kalau kamu baru mengenal BYOK, baca dulu <a href="./../byok/">Pengenalan BYOK</a>.</p><div class="warning custom-block"><p class="custom-block-title">📅 Info penting 2026</p><p>Beda dari semua provider lain di panduan ini: <strong>Featherless tidak punya free tier atau trial API</strong>. Membuat akun bisa tanpa kartu kredit, tapi <strong>API key hanya berfungsi jika langgananmu aktif</strong> — key tanpa plan tidak akan jalan. Jangan mengharapkan kuota gratisan. Halaman ini mengajarkan <strong>cara</strong> yang benar; untuk angka terkini selalu cek halaman resmi <a href="https://featherless.ai/pricing" target="_blank" rel="noreferrer">harga Featherless</a>.</p></div><hr><h2 id="membuat-api-key" tabindex="-1">Membuat API Key <a class="header-anchor" href="#membuat-api-key" aria-label="Permalink to “Membuat API Key”">​</a></h2><ol><li>Daftar di <a href="https://featherless.ai" target="_blank" rel="noreferrer">featherless.ai</a> — dengan email atau OAuth.</li><li><strong>Pilih plan/langganan</strong> (mis. plan Chat) — ingat, key tidak berfungsi sebelum langganan aktif.</li><li>Buka <strong>dashboard → API Keys</strong> → <strong>Create New Key</strong>.</li><li>Salin key-nya — di Featherless, key dipakai sebagai <em>Bearer token</em>.</li></ol><div class="danger custom-block"><p class="custom-block-title">🔒 Wajib: langganan aktif dulu</p><p>Ini <strong>perbedaan terbesar</strong> Featherless dibanding provider lain: API key <strong>tidak berfungsi tanpa langganan aktif</strong>. Banyak orang kaget key-nya error padahal &quot;sudah dibuat dengan benar&quot; — padahal plan-nya belum aktif. Pastikan langgananmu berjalan sebelum menyalakan Featherless di Mikazuki.</p></div><hr><h2 id="mengaktifkan-featherless-di-mikazuki-ai" tabindex="-1">Mengaktifkan Featherless di Mikazuki AI <a class="header-anchor" href="#mengaktifkan-featherless-di-mikazuki-ai" aria-label="Permalink to “Mengaktifkan Featherless di Mikazuki AI”">​</a></h2><p>Ikuti alur BYOK standar dari panduan <a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a>. Ringkasannya untuk Featherless:</p><ol><li>Buka <strong>Settings → Engine</strong>, pilih mode <strong>BYOK</strong>.</li><li>Pada pilihan provider, <strong>pilih entri Featherless bila ada</strong> di daftar; jika tidak ada, pakai provider <strong>OpenAI Compatible</strong> dengan: <ul><li><strong>Base URL</strong>: <code>https://api.featherless.ai/v1</code></li><li><strong>API key</strong>: key Featherless kamu (<em>Bearer token</em>).</li></ul></li><li>Tempel API key yang barusan kamu buat.</li><li>Klik tombol 🔍 <strong>fetch models</strong> — daftar model akan muncul dari katalog Featherless.</li><li>Pilih model, atur <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>, lalu klik simpan.</li></ol><div class="tip custom-block"><p class="custom-block-title">🏷️ Format nama model</p><p>Model Featherless memakai format <code>HuggingFaceOrg/ModelName</code> — contohnya <code>Qwen/Qwen2.5-7B-Instruct</code>. Jangan ketik manual; pakai hasil tombol 🔍 <strong>fetch models</strong> agar tidak salah ketik.</p></div><hr><h2 id="plan-harga" tabindex="-1">Plan &amp; Harga <a class="header-anchor" href="#plan-harga" aria-label="Permalink to “Plan &amp; Harga”">​</a></h2><p>Featherless tidak menjual token per satuan pada plan utamanya — yang dijual adalah <strong>akses flat-rate</strong> ke seluruh katalog:</p><ul><li><strong>Chat plan — $25/bulan</strong> (billed monthly, bisa pause/cancel kapan saja): <strong>token unlimited</strong> (<em>&quot;Length is never billed. Concurrency is the only ceiling&quot;</em>), konteks <strong>32K</strong>, <strong>4 concurrent units</strong>, akses ke <strong>semua</strong> 40.000+ model, dan kompatibel dengan SillyTavern, RisuAI, dan Wyvern. Untuk roleplay dan cerita, <strong>ini plan yang direkomendasikan</strong>.</li><li><strong>Developer plan</strong> — mulai <strong>dari $50/bulan</strong> dalam bentuk kredit: berbasis kredit per token, konteks hingga <strong>256K</strong>, hingga <strong>100 concurrent units</strong>. Ditujukan untuk coding agent dan API produksi.</li><li><strong>Pay-As-You-Go</strong> — isi kredit, bayar per token sistem yang sama dengan Developer plan.</li></ul><p>Aturan pemakaian plan Chat: hanya untuk <strong>chat interaktif yang diketik manusia</strong> — bukan untuk traffic aplikasi/API, <em>reselling</em>, otomasi <em>background</em>, atau <em>benchmarking</em>. Untuk user Mikazuki artinya: pemakaian persona pribadi = OK.</p><div class="warning custom-block"><p class="custom-block-title">⚠️ Jangan kunci angka</p><p>Kami hanya menyebut angka plan di atas sebagaimana tampil di situsnya — detail dan perubahannya bisa saja bergeser. Cek halaman resmi <a href="https://featherless.ai/pricing" target="_blank" rel="noreferrer">harga</a> dan <a href="https://featherless.ai/docs/plans" target="_blank" rel="noreferrer">docs plans</a> untuk angka terkini.</p></div><hr><h2 id="model-katalog" tabindex="-1">Model &amp; Katalog <a class="header-anchor" href="#model-katalog" aria-label="Permalink to “Model &amp; Katalog”">​</a></h2><p>Katalog Featherless berisi <strong>40.000+ model open-weight</strong> — seluruh keluarga besar seperti <strong>Llama, Qwen, DeepSeek, GLM, Kimi</strong>, dan banyak lagi — dan plan Chat membukamu ke <strong>semuanya</strong>, bukan hanya subset.</p><p>Beberapa catatan praktis:</p><ul><li>Model diambil lewat tombol 🔍 <strong>fetch models</strong>; nama mengikuti format <code>HuggingFaceOrg/ModelName</code>.</li><li>Kalau satu model sedang penuh, model <em>sibling</em> dari keluarga/ukuran serupa biasanya tersedia — jangan terpaku pada satu nama.</li><li><strong>Chat box di halaman model</strong> pada situs Featherless hanya untuk <em>testing</em> singkat model tersebut — bukan chat interface penuh untuk pemakaian serius.</li></ul><hr><h2 id="limit-concurrent-units" tabindex="-1">Limit &amp; Concurrent Units <a class="header-anchor" href="#limit-concurrent-units" aria-label="Permalink to “Limit &amp; Concurrent Units”">​</a></h2><p>Di plan Chat, yang membatasi bukan panjang output, melainkan <strong>concurrency</strong>:</p><ul><li><strong>4 concurrent units</strong> — satu unit bisa dibayangkan sebagai satu percakapan model besar (70B), atau empat model kecil yang jalan sekaligus. Kalau habis unit, request berikutnya menunggu.</li><li><strong>&quot;Too many concurrent requests&quot;</strong> adalah penyebab paling umum error selain 503 — kurangi jumlah sesi paralel.</li><li>Plan Developer/PAYG naik hingga <strong>100 concurrent units</strong>, dengan konteks hingga <strong>256K</strong>.</li></ul><p>Di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a>, konteks plan Chat <strong>32K</strong> berarti preset <code>128K</code> tidak realistis — mulai dari nilai yang sesuai, dan ingat <code>max_tokens</code> ikut dipotong dari context window.</p><hr><h2 id="privasi-data" tabindex="-1">Privasi &amp; Data <a class="header-anchor" href="#privasi-data" aria-label="Permalink to “Privasi &amp; Data”">​</a></h2><p>Ini <em>selling point</em> utama Featherless untuk pemakaian roleplay:</p><ul><li><strong>Prompt tidak pernah disimpan</strong> — &quot;Prompts stored: Never&quot;.</li><li>Pemakaian <strong>private, secure, dan anonymous</strong>: tanpa logs untuk chat plan. Prompt dan completions tidak dipakai untuk pelatihan maupun disimpan di server.</li></ul><div class="tip custom-block"><p class="custom-block-title">🛡️ Untuk yang peduli privasi</p><p>Kalau kamu menulis roleplay atau cerita yang tidak ingin ada jejaknya di mana-mana, model &quot;no logs + prompts never stored&quot; ini jadi alasan kuat memilih Featherless dibanding provider lain dengan retention kebijakan lebih longgar.</p></div><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><details class="details custom-block"><summary>HTTP 503 — model saturated</summary><p>Model yang kamu pilih sedang <strong>kejenuhan</strong> (populer sering saturasi dulu). Request yang gagal begini <strong>tidak ditagih</strong>. Tunggu sebentar lalu retry, atau pindah ke model <em>sibling</em> yang lebih sepi dari keluarga/ukuran serupa.</p></details><details class="details custom-block"><summary>Error 401 — key tidak berfungsi</summary><p>Di Featherless, key <strong>tanpa langganan aktif tidak jalan</strong> — beda dari provider gratis yang mungkin biasa kamu pakai, dan sering membuat orang kaget. Buka dashboard dan pastikan plan-mu aktif. Kalau sudah aktif, cek key salah tempel atau terpotong.</p></details><details class="details custom-block"><summary>Kredit habis (Developer / PAYG)</summary><p>Call Developer/PAYG akan di-<em>block</em> sampai kamu <strong>top-up kredit di Billing</strong> — Featherless akan memberi notifikasi saat saldo menyentuh nol. Kredit tidak <em>expire</em>, dan kamu juga bisa top-up satu-off. Kabar baiknya: hanya <em>successful requests</em> yang ditagih.</p></details><details class="details custom-block"><summary>Jawaban terpotong / cerita memangkas bagian lama</summary><p>Plan Chat punya konteks <strong>32K</strong> — percakapan yang sangat panjang akan memangkas bagian paling tua saat melewati batas. Naikkan <code>max_tokens</code> di <a href="./../byok/parameter-dasar.html">Parameter Dasar</a> untuk ruang jawaban lebih besar (ingat, ikut dipotong dari context window), atau pindah ke Developer/PAYG jika benar-benar butuh konteks di atas 32K — plan Chat memang dirancang untuk <em>roleplay</em> sehari-hari.</p></details><hr><h2 id="jelajahi-byok-lebih-lanjut" tabindex="-1">Jelajahi BYOK Lebih Lanjut <a class="header-anchor" href="#jelajahi-byok-lebih-lanjut" aria-label="Permalink to “Jelajahi BYOK Lebih Lanjut”">​</a></h2><ul><li><a href="./../byok/">Pengenalan BYOK</a> — konsep dasar dan cara kerjanya.</li><li><a href="./../byok/instalasi.html">Instalasi &amp; Aktivasi</a> — langkah menyalakan mode BYOK.</li><li><a href="./../byok/parameter-dasar.html">Parameter Dasar</a> — atur <code>max_tokens</code>, <code>context_window</code>, dan parameter kreativitas.</li><li><a href="./deepseek.html">DeepSeek</a> — panduan padanan untuk provider DeepSeek.</li><li><a href="./groq.html">Groq</a> — panduan padanan untuk provider Groq.</li></ul>`,42)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};